import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // a[i]-b[j] == a[j]-b[i]  <=>  a[i]+b[i] == a[j]+b[j]
        HashMap<Long, Integer> cnt = new HashMap<>(4 * n + 16);
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long key = a[i] + nextLong();
            int c = cnt.merge(key, 1, Integer::sum);
            ans += c; // pairs (i, j) with i <= j ending at j, including i == j
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	// a[i]-b[j] == a[j]-b[i]  <=>  a[i]+b[i] == a[j]+b[j]
	cnt := make(map[int]int, n)
	ans := 0
	for i := 0; i < n; i++ {
		key := a[i] + readInt()
		cnt[key]++
		ans += cnt[key] // pairs (i, j) with i <= j ending at j, including i == j
	}
	fmt.Println(ans)
}
